package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.CompilerErrorCode;
import com.google.javascript.jscomp.phases.NodeTraversal;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import org.powermock.api.mockito.PowerMockito;
import org.powermock.core.classloader.annotations.PrepareForTest;
import org.powermock.modules.junit4.PowerMockRunner;
import static com.google.javascript.jscomp.CheckGlobalThis.GLOBAL_THIS;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(PowerMockRunner.class)
@PrepareForTest({CheckGlobalThis.class})
public class CheckGlobalThis_visit_TriageGen2Test {

    private CheckGlobalThis checkGlobalThis;

    @Mock
    private NodeTraversal t;

    @Mock
    private Node n;

    @Mock
    private Node parent;

    @Mock
    private Compiler compiler;

    @Mock
    private CompilerError error;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        // Since we cannot easily instantiate CheckGlobalThis with its private fields 
        // via constructor, we assume it is accessible or we use reflection/spy.
        // For this test, we will use a spy to mock the 'shouldReportThis' and 'compiler' access.
        checkGlobalThis = PowerMockito.spy(new CheckGlobalThis());

        // Injecting compiler via reflection as it is likely a private field
        try {
            java.lang.reflect.Field compilerField = CheckGlobalThis.class.getDeclaredField("compiler");
            compilerField.setAccessible(true);
            compilerField.set(checkGlobalThis, compiler);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testVisit_ReportsErrorWhenThisIsGlobal() {
        // Arrange
        when(n.getType()).thenReturn(Token.THIS);
        PowerMockito.doReturn(true).when(checkGlobalThis).shouldReportThis(n, parent);
        when(t.makeError(n, any(), any())).thenReturn(error);

        // Act
        checkGlobalThis.visit(t, n, parent);

        // Assert
        verify(t).makeError(n, any(), any());
        verify(compiler).report(error);
    }

    @Test
    public void testVisit_DoesNotReportErrorWhenShouldNotReportThis() {
        // Arrange
        when(n.getType()).thenReturn(Token.THIS);
        PowerMockito.doReturn(false).when(checkGlobalThis).shouldReportThis(n, parent);

        // Act
        checkGlobalThis.visit(t, n, parent);

        // Assert: No error reported
        verify(compiler, org.mockito.Mockito.never()).report(any());
    }

    @Test
    public void testVisit_DoesNotReportErrorWhenNotThis() {
        // Arrange
        when(n.getType()).thenReturn(Token.NAME);
        PowerMockito.doReturn(true).when(checkGlobalThis).shouldReportThis(n, parent);

        // Act
        checkGlobalThis.visit(t, n, parent);

        // Assert: No error reported
        verify(compiler, org.mockito.Mockito.never()).report(any());
    }

    @Test
    public void testVisit_ClearsAssignLhsChild() throws Exception {
        // Arrange
        when(n.getType()).thenReturn(Token.NAME);

        // Use reflection to set assignLhsChild to a dummy node
        Node dummyNode = org.mockito.Mockito.mock(Node.class);
        java.lang.reflect.Field lhsField = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
        lhsField.setAccessible(true);
        lhsField.set(checkGlobalThis, dummyNode);

        // Act
        // We need to make sure n == assignLhsChild. 
        // Since n is a mock, we set the field to n.
        lhsField.set(checkGlobalThis, n);

        checkGlobalThis.visit(t, n, parent);

        // Assert
        assertNull("assignLhsChild should be null after visit", lhsField.get(checkGlobalThis));
    }

    @Test
    public void testVisit_DoesNotClearAssignLhsChildWhenNotMatch() throws Exception {
        // Arrange
        when(n.getType()).thenReturn(Token.NAME);
        Node otherNode = org.mockito.Mockito.mock(Node.class);

        java.lang.reflect.Field lhsField = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
        lhsField.setAccessible(true);
        lhsField.set(checkGlobalThis, otherNode);

        // Act
        checkGlobalThis.visit(t, n, parent);

        // Assert
        assertNull(false); // Dummy check
        org.junit.Assert.assertEquals(otherNode, lhsField.get(checkGlobalThis));
    }
}
